/**
 * WP-2 — Player stat sampler. Turns a projection (expected full-game stat line) plus this sim's TeamScript
 * into one simulated raw stat line.
 *
 * Owner: WP-2. Imports allowed: '@fmm/core'.
 */
import { STAT_CATALOG, TD_FACTOR_EXPONENT } from '@fmm/core';
import type { PlayerProjection, PlayerLive, StatLine, Rng, TeamScript } from '@fmm/core';

/** Chance a player who has not finished suffers a game-ending injury / benching, per full game. */
export const EARLY_EXIT_RATE = 0.03;
/** Injury-status handling: multiply expected stats by this; 'Out', 'IR', 'Suspended', 'PUP' -> 0 (status 'out'). */
export const INJURY_MULTIPLIER: Readonly<Record<string, number>> = {
  Questionable: 0.85,
  Doubtful: 0.25,
  Out: 0,
  IR: 0,
  PUP: 0,
  Suspended: 0,
  NA: 0,
};

const hasOwn = (o: object, k: string): boolean => Object.prototype.hasOwnProperty.call(o, k);

/** Injury multiplier for a status string; unknown or missing statuses count as healthy (1). */
function injuryMultiplier(status: string | null | undefined): number {
  if (!status || !hasOwn(INJURY_MULTIPLIER, status)) return 1;
  const m = INJURY_MULTIPLIER[status];
  return typeof m === 'number' && Number.isFinite(m) && m >= 0 ? m : 1;
}

/** Share of the game still to play, clamped to [0, 1]. Missing or NaN means not started (1). */
function remainingFraction(live?: PlayerLive): number {
  const f = live?.fractionRemaining;
  if (typeof f !== 'number' || Number.isNaN(f)) return 1;
  return Math.min(1, Math.max(0, f));
}

/** A script multiplier: finite and non-negative, otherwise neutral (1). */
function factor(x: number | undefined): number {
  return typeof x === 'number' && Number.isFinite(x) && x >= 0 ? x : 1;
}

/** A stat value that is finite and positive, otherwise 0. */
function cleanValue(v: unknown): number {
  return typeof v === 'number' && Number.isFinite(v) && v > 0 ? v : 0;
}

/** Copy of live.actual with every value sanitized. */
function copyActual(live?: PlayerLive): StatLine {
  const out: StatLine = {};
  if (!live || !live.actual) return out;
  for (const [k, v] of Object.entries(live.actual)) out[k] = cleanValue(v);
  return out;
}

/**
 * Sample one simulated week for one player.
 *
 * Inputs: proj (may be undefined -> player unknown/bye -> return actual stats only, or {}),
 *   script = TeamScript of the player's NFL team in this sim, oppScript = opponent's TeamScript (or undefined),
 *   live = PlayerLive (undefined = not started, fractionRemaining 1, actual {}).
 *
 * Algorithm:
 *  1. r = live?.fractionRemaining ?? 1. If r <= 0 return a copy of live.actual.
 *  2. m = INJURY_MULTIPLIER[proj.injuryStatus] ?? 1 (only applies when r === 1; a player already playing is active).
 *  3. Early exit: with probability EARLY_EXIT_RATE * r, scale this sim's remaining stats by U(0, 1) (one draw).
 *  4. For every StatDef in STAT_CATALOG with proj.mean[key] > 0 (and position-appropriate):
 *       base = proj.mean[key] * r * m * exitScale
 *       driver multiplier f: 'pass' -> script.passFactor, 'rush' -> script.rushFactor, 'points' -> script.pointsFactor,
 *         'oppPass' -> oppScript?.passFactor ?? 1, 'none' -> 1.
 *       kind 'volume': rng.gammaMeanCv(base * f, def.cv)
 *       kind 'count' : rng.poisson(base * f)
 *       kind 'td'    : rng.poisson(base * Math.pow(f, TD_FACTOR_EXPONENT))
 *       kind 'script': skip here.
 *     Receptions can never exceed targets when both present: rec = min(rec, rec_tgt) only if rec_tgt was sampled.
 *  5. DEF (proj.position === 'DEF'): set pts_allow = script.pointsAllowed and yds_allow = script.yardsAllowed
 *     (these come from the game script, already final-score based, so do NOT add live.actual for these two keys).
 *  6. Add live.actual for every other key (actual + sampled remainder).
 *  7. Return only finite, >= 0 numbers. Never NaN.
 *
 * Must be fast: no object allocation beyond the returned StatLine.
 */
/** Per-projection list of the stats to sample, built once (the hot loop runs ~1M times per pricing). */
interface CompiledStat { key: string; kind: 0 | 1 | 2; driver: 0 | 1 | 2 | 3 | 4; cv: number; mu: number }
const compiledCache = new WeakMap<PlayerProjection, CompiledStat[]>();
function compile(proj: PlayerProjection): CompiledStat[] {
  const hit = compiledCache.get(proj);
  if (hit) return hit;
  const mean = proj.mean ?? {};
  const list: CompiledStat[] = [];
  for (const def of STAT_CATALOG) {
    if (def.kind === 'script') continue;
    if (!hasOwn(mean, def.key)) continue;
    const mu = mean[def.key];
    if (typeof mu !== 'number' || !(mu > 0) || !Number.isFinite(mu)) continue;
    list.push({
      key: def.key,
      kind: def.kind === 'volume' ? 0 : def.kind === 'count' ? 1 : 2,
      driver: def.driver === 'pass' ? 1 : def.driver === 'rush' ? 2 : def.driver === 'points' ? 3 : def.driver === 'oppPass' ? 4 : 0,
      cv: def.cv ?? 0,
      mu,
    });
  }
  compiledCache.set(proj, list);
  return list;
}

export function sampleStatLine(
  proj: PlayerProjection | undefined,
  script: TeamScript | undefined,
  oppScript: TeamScript | undefined,
  rng: Rng,
  live?: PlayerLive,
): StatLine {
  const r = remainingFraction(live);
  if (r <= 0 || !proj) return copyActual(live);

  const m = r >= 1 ? injuryMultiplier(proj.injuryStatus) : 1;

  // Early exit: one Bernoulli draw, then one U(0,1) scale shared by every stat this sim.
  let exitScale = 1;
  if (rng.next() < EARLY_EXIT_RATE * r) exitScale = rng.next();
  const scale = r * m * exitScale;

  const out: StatLine = {};
  const compiled = compile(proj);
  const fPass = factor(script?.passFactor), fRush = factor(script?.rushFactor), fPts = factor(script?.pointsFactor);
  const fOpp = factor(oppScript?.passFactor);

  for (let i = 0; i < compiled.length; i++) {
    const c = compiled[i];
    const f = c.driver === 1 ? fPass : c.driver === 2 ? fRush : c.driver === 3 ? fPts : c.driver === 4 ? fOpp : 1;
    const base = c.mu * scale;
    let v: number;
    if (c.kind === 0) v = rng.gammaMeanCv(base * f, c.cv);
    else if (c.kind === 1) v = rng.poisson(base * f);
    else v = rng.poisson(base * (f === 1 ? 1 : Math.pow(f, TD_FACTOR_EXPONENT)));
    out[c.key] = v > 0 && Number.isFinite(v) ? v : 0;
  }

  const isDef = proj.position === 'DEF';
  if (isDef && script) {
    out.pts_allow = cleanValue(script.pointsAllowed);
    out.yds_allow = cleanValue(script.yardsAllowed);
  }

  if (live && live.actual) {
    for (const [k, v] of Object.entries(live.actual)) {
      if (isDef && (k === 'pts_allow' || k === 'yds_allow')) continue;
      const prev = hasOwn(out, k) ? out[k] : 0;
      out[k] = prev + cleanValue(v);
    }
  }

  // Receptions can never exceed targets. Applied to the season-to-date totals so the invariant holds
  // even when actual stats are already recorded.
  if (hasOwn(out, 'rec') && hasOwn(out, 'rec_tgt') && out.rec > out.rec_tgt) out.rec = out.rec_tgt;

  return out;
}

/** 'final' when live.fractionRemaining === 0; 'out' when injury multiplier is 0 and not started;
 *  'live' when 0 < r < 1; else 'upcoming'. */
export function playerStatus(proj: PlayerProjection | undefined, live?: PlayerLive): 'final' | 'live' | 'upcoming' | 'out' {
  const r = remainingFraction(live);
  if (r <= 0) return 'final';
  if (r >= 1 && proj && injuryMultiplier(proj.injuryStatus) === 0) return 'out';
  if (r < 1) return 'live';
  return 'upcoming';
}
