/// <reference lib="webworker" />
/** Runs the odds engine off the main thread. Owner: Commander. */
import { priceLeague } from '@fmm/engine';
import type { League, WeekContext, MatchupPrice } from '@fmm/core';

export interface PriceRequest { id: number; league: League; ctx: WeekContext; sims: number; seed?: number }
export interface PriceResponse { id: number; prices?: MatchupPrice[]; ms: number; error?: string }

self.onmessage = (e: MessageEvent<PriceRequest>) => {
  const { id, league, ctx, sims, seed } = e.data;
  const t0 = performance.now();
  try {
    const prices = priceLeague(league, ctx, { sims, seed });
    (self as unknown as Worker).postMessage({ id, prices, ms: performance.now() - t0 } satisfies PriceResponse);
  } catch (err) {
    (self as unknown as Worker).postMessage({ id, ms: performance.now() - t0, error: String((err as Error)?.message ?? err) } satisfies PriceResponse);
  }
};
