/**
 * Canonical catalog of raw stats the simulator samples and the scorer understands.
 * Keys are Sleeper stat keys (verified against live Sleeper weekly projection rows, 2026-10-26).
 * Owner: Commander.
 *
 * kind:
 *  - 'volume': continuous yardage-like stat. Sample Gamma(mean, cv).
 *  - 'count' : small counts (receptions, attempts, ints, sacks, FGs). Sample Poisson(mean).
 *  - 'td'    : touchdowns / 2-pt conversions. Sample Poisson(mean * factor^TD_FACTOR_EXPONENT).
 *  - 'script': not sampled from the player's mean; taken from the TeamScript (DEF pts_allow, yds_allow).
 *
 * driver: which TeamScript multiplier scales the stat ('pass' -> passFactor, 'rush' -> rushFactor,
 * 'points' -> pointsFactor, 'oppPass' -> the OPPONENT's passFactor (more opponent dropbacks = more sacks/INTs), 'none' -> unscaled).
 */
export type StatKind = 'volume' | 'count' | 'td' | 'script';
export type StatDriver = 'pass' | 'rush' | 'points' | 'oppPass' | 'none';

export interface StatDef {
  key: string;
  kind: StatKind;
  driver: StatDriver;
  /** Coefficient of variation for 'volume' stats. */
  cv?: number;
}

export const TD_FACTOR_EXPONENT = 1.4;

export const STAT_CATALOG: readonly StatDef[] = [
  // passing
  { key: 'pass_att', kind: 'count', driver: 'pass' },
  { key: 'pass_cmp', kind: 'count', driver: 'pass' },
  { key: 'pass_yd', kind: 'volume', driver: 'pass', cv: 0.3 },
  { key: 'pass_td', kind: 'td', driver: 'pass' },
  { key: 'pass_int', kind: 'count', driver: 'none' },
  { key: 'pass_2pt', kind: 'td', driver: 'pass' },
  { key: 'pass_sack', kind: 'count', driver: 'none' },
  // rushing
  { key: 'rush_att', kind: 'count', driver: 'rush' },
  { key: 'rush_yd', kind: 'volume', driver: 'rush', cv: 0.55 },
  { key: 'rush_td', kind: 'td', driver: 'rush' },
  { key: 'rush_2pt', kind: 'td', driver: 'rush' },
  // receiving
  { key: 'rec_tgt', kind: 'count', driver: 'pass' },
  { key: 'rec', kind: 'count', driver: 'pass' },
  { key: 'rec_yd', kind: 'volume', driver: 'pass', cv: 0.6 },
  { key: 'rec_td', kind: 'td', driver: 'pass' },
  { key: 'rec_2pt', kind: 'td', driver: 'pass' },
  // misc offense
  { key: 'fum', kind: 'count', driver: 'none' },
  { key: 'fum_lost', kind: 'count', driver: 'none' },
  // kicking
  { key: 'fgm_0_19', kind: 'count', driver: 'points' },
  { key: 'fgm_20_29', kind: 'count', driver: 'points' },
  { key: 'fgm_30_39', kind: 'count', driver: 'points' },
  { key: 'fgm_40_49', kind: 'count', driver: 'points' },
  { key: 'fgm_50p', kind: 'count', driver: 'points' },
  { key: 'fgmiss', kind: 'count', driver: 'none' },
  { key: 'xpm', kind: 'count', driver: 'points' },
  { key: 'xpmiss', kind: 'count', driver: 'none' },
  // team defense / special teams
  { key: 'sack', kind: 'count', driver: 'oppPass' },
  { key: 'int', kind: 'count', driver: 'oppPass' },
  { key: 'fum_rec', kind: 'count', driver: 'none' },
  { key: 'ff', kind: 'count', driver: 'none' },
  { key: 'safe', kind: 'count', driver: 'none' },
  { key: 'blk_kick', kind: 'count', driver: 'none' },
  { key: 'def_td', kind: 'td', driver: 'none' },
  { key: 'def_st_td', kind: 'td', driver: 'none' },
  { key: 'pts_allow', kind: 'script', driver: 'none' },
  { key: 'yds_allow', kind: 'script', driver: 'none' },
];

export const STAT_INDEX: Readonly<Record<string, StatDef>> = Object.fromEntries(STAT_CATALOG.map((s) => [s.key, s]));

/** Keep only catalog keys with finite positive values. Drops pts_ppr, adp_*, rank keys, bonus_* inputs, etc. */
export function cleanStatLine(raw: Record<string, unknown>): Record<string, number> {
  const out: Record<string, number> = {};
  for (const def of STAT_CATALOG) {
    const v = raw[def.key];
    if (typeof v === 'number' && Number.isFinite(v) && v > 0) out[def.key] = v;
  }
  // Sleeper reports total FGs as `fgm` with distance buckets; if only `fgm` exists, put it in 30-39.
  const fgmTotal = raw['fgm'];
  const hasBuckets = ['fgm_0_19', 'fgm_20_29', 'fgm_30_39', 'fgm_40_49', 'fgm_50p'].some((k) => k in out);
  if (!hasBuckets && typeof fgmTotal === 'number' && fgmTotal > 0) out['fgm_30_39'] = fgmTotal;
  return out;
}
