/**
 * WP-3 — League scoring. Applies a league's own Sleeper `scoring_settings` to a raw stat line.
 * The same raw stats are scored as PPR, half-PPR, 6-pt passing TDs, TE premium, etc.
 *
 * Owner: WP-3. Imports allowed: '@fmm/core'.
 */
import type { ScoringRules, StatLine, Position } from '@fmm/core';
import { STAT_CATALOG } from '@fmm/core';

/** Sleeper's default full-PPR scoring (offense, K, DEF). Used when a league gives no scoring_settings. */
export const DEFAULT_PPR: ScoringRules = {
  pass_yd: 0.04, pass_td: 4, pass_int: -1, pass_2pt: 2,
  rush_yd: 0.1, rush_td: 6, rush_2pt: 2,
  rec: 1, rec_yd: 0.1, rec_td: 6, rec_2pt: 2,
  fum_lost: -2,
  fgm_0_19: 3, fgm_20_29: 3, fgm_30_39: 3, fgm_40_49: 4, fgm_50p: 5, fgmiss: -1, xpm: 1, xpmiss: -1,
  sack: 1, int: 2, fum_rec: 2, safe: 2, ff: 1, blk_kick: 2, def_td: 6, def_st_td: 6,
  pts_allow_0: 10, pts_allow_1_6: 7, pts_allow_7_13: 4, pts_allow_14_20: 1,
  pts_allow_21_27: 0, pts_allow_28_34: -1, pts_allow_35p: -4,
};

export const HALF_PPR: ScoringRules = { ...DEFAULT_PPR, rec: 0.5 };
export const STANDARD: ScoringRules = { ...DEFAULT_PPR, rec: 0 };

// ---------------------------------------------------------------------------------------------
// Derived-stat tables. Shared by deriveStats (reference path) and scoreStatLine (hot path) so the
// two cannot drift apart.
// ---------------------------------------------------------------------------------------------

/** Stat keys the scorer reads from a raw line. Input keys outside this set are ignored. */
const CATALOG_KEYS: ReadonlySet<string> = new Set(STAT_CATALOG.map((s) => s.key));

interface YardBonus { readonly key: string; readonly stat: string; readonly min: number }

const YARD_BONUSES: readonly YardBonus[] = [
  { key: 'bonus_pass_yd_300', stat: 'pass_yd', min: 300 },
  { key: 'bonus_pass_yd_400', stat: 'pass_yd', min: 400 },
  { key: 'bonus_rush_yd_100', stat: 'rush_yd', min: 100 },
  { key: 'bonus_rush_yd_200', stat: 'rush_yd', min: 200 },
  { key: 'bonus_rec_yd_100', stat: 'rec_yd', min: 100 },
  { key: 'bonus_rec_yd_200', stat: 'rec_yd', min: 200 },
];

const PTS_ALLOW_KEYS = [
  'pts_allow_0', 'pts_allow_1_6', 'pts_allow_7_13', 'pts_allow_14_20',
  'pts_allow_21_27', 'pts_allow_28_34', 'pts_allow_35p',
] as const;

const YDS_ALLOW_KEYS = [
  'yds_allow_0_100', 'yds_allow_100_199', 'yds_allow_200_299', 'yds_allow_300_349', 'yds_allow_350_399',
  'yds_allow_400_449', 'yds_allow_450_499', 'yds_allow_500_549', 'yds_allow_550p',
] as const;

/** Points allowed are rounded to the nearest integer, then bucketed. Input must be finite. */
function ptsAllowBucket(points: number): string {
  const p = Math.max(0, Math.round(points));
  if (p === 0) return 'pts_allow_0';
  if (p <= 6) return 'pts_allow_1_6';
  if (p <= 13) return 'pts_allow_7_13';
  if (p <= 20) return 'pts_allow_14_20';
  if (p <= 27) return 'pts_allow_21_27';
  if (p <= 34) return 'pts_allow_28_34';
  return 'pts_allow_35p';
}

/** Yards allowed are rounded to the nearest integer, then bucketed. Input must be finite. */
function ydsAllowBucket(yards: number): string {
  const y = Math.max(0, Math.round(yards));
  if (y < 100) return 'yds_allow_0_100';
  if (y < 200) return 'yds_allow_100_199';
  if (y < 300) return 'yds_allow_200_299';
  if (y < 350) return 'yds_allow_300_349';
  if (y < 400) return 'yds_allow_350_399';
  if (y < 450) return 'yds_allow_400_449';
  if (y < 500) return 'yds_allow_450_499';
  if (y < 550) return 'yds_allow_500_549';
  return 'yds_allow_550p';
}

/** Position-specific reception bonus key, or undefined when the position has none. */
function recBonusKey(position: string): string | undefined {
  switch (position) {
    case 'TE': return 'bonus_rec_te';
    case 'RB': return 'bonus_rec_rb';
    case 'WR': return 'bonus_rec_wr';
    default: return undefined;
  }
}

/** Keys that deriveStats recomputes; any such key in the input is ignored. */
function isRecomputedKey(key: string): boolean {
  return key.startsWith('bonus_') || key.startsWith('pts_allow_') || key.startsWith('yds_allow_');
}

/** A finite raw stat, or 0 when missing or non-numeric. */
function statOf(raw: StatLine | null | undefined, key: string): number {
  if (raw == null) return 0;
  const v = raw[key];
  return typeof v === 'number' && Number.isFinite(v) ? v : 0;
}

/** A finite raw stat, or undefined when missing or non-numeric. */
function statOrUndef(raw: StatLine | null | undefined, key: string): number | undefined {
  if (raw == null) return undefined;
  const v = raw[key];
  return typeof v === 'number' && Number.isFinite(v) ? v : undefined;
}

/** A finite rule weight, or 0 when the league does not score that key. */
function weightOf(rules: ScoringRules, key: string): number {
  const w = rules[key];
  return typeof w === 'number' && Number.isFinite(w) ? w : 0;
}

function round2(x: number): number {
  const r = Math.round(x * 100) / 100;
  // Avoid returning -0, and never return NaN or Infinity.
  if (!Number.isFinite(r)) return 0;
  return r === 0 ? 0 : r;
}

/**
 * Derive Sleeper "bucket" and "bonus" stats from raw stats so threshold rules score correctly:
 *  - pts_allow -> exactly one of pts_allow_0, pts_allow_1_6, pts_allow_7_13, pts_allow_14_20, pts_allow_21_27,
 *    pts_allow_28_34, pts_allow_35p set to 1 (round pts_allow to nearest integer first).
 *  - yds_allow -> one of yds_allow_0_100, yds_allow_100_199, yds_allow_200_299, yds_allow_300_349,
 *    yds_allow_350_399, yds_allow_400_449, yds_allow_450_499, yds_allow_500_549, yds_allow_550p = 1.
 *  - bonus_pass_yd_300 (pass_yd >= 300), bonus_pass_yd_400 (>= 400), bonus_rush_yd_100, bonus_rush_yd_200,
 *    bonus_rec_yd_100, bonus_rec_yd_200 = 1 when reached (both 100 and 200 can be 1).
 *  - Position reception bonuses: bonus_rec_te = rec when position TE, bonus_rec_rb when RB, bonus_rec_wr when WR.
 *  - Sleeper also scores per-FG-yard (fgm_yds) and 1st downs; ignore keys we cannot derive.
 * Input bonus_* keys are IGNORED and recomputed. Returns a NEW object containing raw + derived keys.
 */
export function deriveStats(raw: StatLine, position: Position | 'UNK'): StatLine {
  const out: StatLine = {};
  if (raw != null) {
    for (const k in raw) {
      if (isRecomputedKey(k)) continue;
      const v = raw[k];
      if (typeof v === 'number' && Number.isFinite(v)) out[k] = v;
    }
  }

  for (const b of YARD_BONUSES) {
    out[b.key] = statOf(out, b.stat) >= b.min ? 1 : 0;
  }

  const rec = statOf(out, 'rec');
  out.bonus_rec_te = position === 'TE' ? rec : 0;
  out.bonus_rec_rb = position === 'RB' ? rec : 0;
  out.bonus_rec_wr = position === 'WR' ? rec : 0;

  const pa = statOrUndef(out, 'pts_allow');
  if (pa !== undefined) {
    const hit = ptsAllowBucket(pa);
    for (const k of PTS_ALLOW_KEYS) out[k] = k === hit ? 1 : 0;
  }
  const ya = statOrUndef(out, 'yds_allow');
  if (ya !== undefined) {
    const hit = ydsAllowBucket(ya);
    for (const k of YDS_ALLOW_KEYS) out[k] = k === hit ? 1 : 0;
  }
  return out;
}

/**
 * Fantasy points = sum over keys k in rules of rules[k] * derived[k] (missing stat = 0).
 * Unknown rule keys are ignored. Result rounded to 2 decimals (Sleeper displays 2). Never NaN.
 *
 * Hot path: iterates the line's own catalog keys and the few derived keys, without building the derived
 * object. Gives the same result as summing deriveStats(raw, position) over the rules, up to float rounding.
 * A null/undefined rules argument falls back to DEFAULT_PPR.
 */
export function scoreStatLine(raw: StatLine, rules: ScoringRules, position: Position | 'UNK'): number {
  const r: ScoringRules = rules ?? DEFAULT_PPR;
  let total = 0;

  if (raw != null) {
    for (const k in raw) {
      if (!CATALOG_KEYS.has(k)) continue;
      const v = raw[k];
      if (typeof v !== 'number' || !Number.isFinite(v)) continue;
      total += weightOf(r, k) * v;
    }
  }

  // Yardage bonuses, same thresholds as YARD_BONUSES (kept unrolled for the hot path).
  const passYd = statOf(raw, 'pass_yd');
  if (passYd >= 300) total += weightOf(r, 'bonus_pass_yd_300');
  if (passYd >= 400) total += weightOf(r, 'bonus_pass_yd_400');
  const rushYd = statOf(raw, 'rush_yd');
  if (rushYd >= 100) total += weightOf(r, 'bonus_rush_yd_100');
  if (rushYd >= 200) total += weightOf(r, 'bonus_rush_yd_200');
  const recYd = statOf(raw, 'rec_yd');
  if (recYd >= 100) total += weightOf(r, 'bonus_rec_yd_100');
  if (recYd >= 200) total += weightOf(r, 'bonus_rec_yd_200');

  const recKey = recBonusKey(position);
  if (recKey !== undefined) total += weightOf(r, recKey) * statOf(raw, 'rec');

  const pa = statOrUndef(raw, 'pts_allow');
  if (pa !== undefined) total += weightOf(r, ptsAllowBucket(pa));

  const ya = statOrUndef(raw, 'yds_allow');
  if (ya !== undefined) total += weightOf(r, ydsAllowBucket(ya));

  return round2(total);
}

/**
 * Normalize a Sleeper scoring_settings object: keep finite numeric values only; if empty/undefined return
 * DEFAULT_PPR. Do not merge defaults into a non-empty object (a league that omits DEF keys has no DEF scoring).
 */
export function normalizeScoring(raw: Record<string, unknown> | null | undefined): ScoringRules {
  const out: ScoringRules = {};
  let kept = 0;
  if (raw != null && typeof raw === 'object') {
    for (const k of Object.keys(raw)) {
      const v = raw[k];
      if (typeof v === 'number' && Number.isFinite(v)) {
        out[k] = v;
        kept++;
      }
    }
  }
  return kept === 0 ? { ...DEFAULT_PPR } : out;
}

/** "PPR" | "Half PPR" | "Standard" | "Custom" label from rec value and pass_td (6-pt pass TD -> "Custom"). */
export function scoringLabel(rules: ScoringRules): string {
  const r: ScoringRules = rules ?? DEFAULT_PPR;
  if (weightOf(r, 'pass_td') !== 4) return 'Custom';
  const rec = weightOf(r, 'rec');
  if (rec === 1) return 'PPR';
  if (rec === 0.5) return 'Half PPR';
  if (rec === 0) return 'Standard';
  return 'Custom';
}
