/**
 * WP-4 — Matchup pricing. Orchestrates game scripts -> player stats -> league scoring -> win probability.
 * This is the ONE number: the UI, the bot and the market all call these functions with the same seed.
 *
 * Owner: WP-4. Imports allowed: '@fmm/core', './gameScript', './players', './scoring'.
 */
import type {
  League, WeekContext, PriceOptions, MatchupPrice, SimResult, Position, ScoringRules,
  Driver, Quantiles, PlayerProjection, PlayerLive, TeamScript, GameScriptSims, NflGame, FantasyTeam,
} from '@fmm/core';
import { createRng, seedFrom, SCRIPT_FIELDS, SCRIPT_STRIDE } from '@fmm/core';
import { simulateGameScripts } from './gameScript';
import { sampleStatLine, playerStatus } from './players';
import { scoreStatLine } from './scoring';

export const MODEL_VERSION = 'fmm-sim-0.1';
export const DEFAULT_SIMS = 10000;

/** Injected dependencies (defaults are the real modules). Tests may pass fakes. */
export interface PricingDeps {
  simulateGameScripts: typeof simulateGameScripts;
  sampleStatLine: typeof sampleStatLine;
  scoreStatLine: typeof scoreStatLine;
  playerStatus: typeof playerStatus;
}
export const defaultDeps: PricingDeps = { simulateGameScripts, sampleStatLine, scoreStatLine, playerStatus };

const TIE_EPS = 1e-9;
const SWING_MIN_SD = 0.01;
const TOP_DRIVERS = 3;

// Offsets of each TeamScript field inside a GameScriptSims row (SCRIPT_FIELDS order).
const K_POINTS = SCRIPT_FIELDS.indexOf('pointsFactor');
const K_PASS = SCRIPT_FIELDS.indexOf('passFactor');
const K_RUSH = SCRIPT_FIELDS.indexOf('rushFactor');
const K_PTS_ALLOW = SCRIPT_FIELDS.indexOf('pointsAllowed');
const K_YDS_ALLOW = SCRIPT_FIELDS.indexOf('yardsAllowed');

function hasOwn(rec: object, key: string): boolean {
  return Object.prototype.hasOwnProperty.call(rec, key);
}

/** A lineup slot is a real player unless it is an empty slot ("0" or ""). */
function isPlayerSlot(id: string): boolean {
  return id !== '' && id !== '0';
}

/** Distinct real player ids of a lineup, in first-seen order. */
function uniqueStarters(lineup: readonly string[]): string[] {
  const seen = new Set<string>();
  const out: string[] = [];
  for (const id of lineup) {
    if (!isPlayerSlot(id) || seen.has(id)) continue;
    seen.add(id);
    out.push(id);
  }
  return out;
}

function projectionOf(ctx: WeekContext, id: string): PlayerProjection | undefined {
  return hasOwn(ctx.projections, id) ? ctx.projections[id] : undefined;
}

function liveOf(ctx: WeekContext, id: string): PlayerLive | undefined {
  return ctx.live && hasOwn(ctx.live, id) ? ctx.live[id] : undefined;
}

/**
 * Index of the opponent's script row for a projection, or -1. Uses proj.opponent when it has a row,
 * otherwise the other side of proj's game (by gameId, then by team lookup over the week's games).
 */
function opponentIndex(
  proj: PlayerProjection,
  teamIndex: Record<string, number>,
  gameById: Map<string, NflGame>,
  teamOpponent: Map<string, string>,
): number {
  if (proj.opponent && hasOwn(teamIndex, proj.opponent)) return teamIndex[proj.opponent];
  let other: string | undefined;
  const game = proj.gameId ? gameById.get(proj.gameId) : undefined;
  if (game) {
    if (game.home === proj.team) other = game.away;
    else if (game.away === proj.team) other = game.home;
  }
  if (other === undefined) other = teamOpponent.get(proj.team);
  return other !== undefined && hasOwn(teamIndex, other) ? teamIndex[other] : -1;
}

function meanOf(arr: Float64Array): number {
  let sum = 0;
  for (let i = 0; i < arr.length; i++) sum += arr[i];
  return sum / arr.length;
}

function popSd(arr: Float64Array, mean: number): number {
  let ss = 0;
  for (let i = 0; i < arr.length; i++) {
    const d = arr[i] - mean;
    ss += d * d;
  }
  return Math.sqrt(ss / arr.length);
}

/** Nearest-rank quantiles of an already-sorted array. */
function nearestRank(sorted: Float64Array, p: number): number {
  const n = sorted.length;
  const idx = Math.min(n - 1, Math.max(0, Math.ceil(p * n) - 1));
  return sorted[idx];
}

function quantilesOf(arr: Float64Array): Quantiles {
  const sorted = Float64Array.from(arr).sort();
  return { p10: nearestRank(sorted, 0.1), p50: nearestRank(sorted, 0.5), p90: nearestRank(sorted, 0.9) };
}

/**
 * Impact of one player on pWinA: mean winRateA over the sims where the player is in his top third, minus the
 * same over his bottom third. `score[i]` is A's win rate in sim i (1, 0.5 tie, 0). Ties in the player's points
 * at a cut-off are broken by sim index, so each third holds exactly `third` sims.
 */
function tierImpact(arr: Float64Array, score: Float64Array, third: number): number {
  const n = arr.length;
  const sorted = Float64Array.from(arr).sort();
  const tLow = sorted[third - 1];
  const tHigh = sorted[n - third];

  let lowSum = 0, lowCount = 0, highSum = 0, highCount = 0;
  for (let i = 0; i < n; i++) {
    const v = arr[i];
    if (v < tLow) { lowSum += score[i]; lowCount++; }
    if (v > tHigh) { highSum += score[i]; highCount++; }
  }
  for (let i = 0; i < n && lowCount < third; i++) {
    if (arr[i] === tLow) { lowSum += score[i]; lowCount++; }
  }
  for (let i = 0; i < n && highCount < third; i++) {
    if (arr[i] === tHigh) { highSum += score[i]; highCount++; }
  }
  return highSum / third - lowSum / third;
}

/**
 * Run the shared simulation for any set of lineups.
 *
 * lineups: key -> starter playerIds (empty slots "0"/"" and duplicates within a lineup are ignored;
 *   the same player may appear in several lineups, e.g. two snapshot series — he is sampled ONCE per sim and
 *   the same points count in every lineup that holds him).
 * Steps:
 *  1. rng = createRng(seed). Collect unique player ids across lineups.
 *  2. extraTeams = teams of projected players not found in ctx.games.
 *  3. scripts = deps.simulateGameScripts(ctx.games, sims, rng, extraTeams).
 *  4. For sim s, for each unique player p: proj = ctx.projections[p]; team script = scripts row for proj.team;
 *     opponent script = row for proj.opponent if present (else the other team in proj's game, else undefined);
 *     stats = deps.sampleStatLine(proj, script, opp, rng, ctx.live?.[p]);
 *     pts = deps.scoreStatLine(stats, scoring, proj?.position ?? 'UNK'); playerPoints[p][s] = pts.
 *     Players with no projection and no live stats score 0 every sim.
 *  5. teamPoints[key][s] = sum of its starters' points.
 * Deterministic: same inputs + seed -> identical arrays. Iterate players in sorted id order.
 */
export function simulateLineups(
  lineups: Record<string, string[]>,
  scoring: ScoringRules,
  ctx: WeekContext,
  sims: number,
  seed: number,
  deps: PricingDeps = defaultDeps,
): SimResult {
  if (!Number.isInteger(sims) || sims < 1) throw new RangeError(`simulateLineups: sims must be a positive integer, got ${sims}`);

  const rng = createRng(seed);

  // 1. Lineups and unique players (sorted for determinism).
  const keys = Object.keys(lineups).sort();
  const starters = new Map<string, string[]>();
  const playerSet = new Set<string>();
  for (const key of keys) {
    const list = uniqueStarters(lineups[key]);
    starters.set(key, list);
    for (const p of list) playerSet.add(p);
  }
  const playerIds = [...playerSet].sort();

  // 2. Teams of projected players that have no game this week.
  const gameTeams = new Set<string>();
  for (const g of ctx.games) { gameTeams.add(g.home); gameTeams.add(g.away); }
  const extraTeams: string[] = [];
  const extraSeen = new Set<string>();
  for (const p of playerIds) {
    const proj = projectionOf(ctx, p);
    if (!proj || gameTeams.has(proj.team) || extraSeen.has(proj.team)) continue;
    extraSeen.add(proj.team);
    extraTeams.push(proj.team);
  }

  // 3. One shared set of game scripts for every lineup.
  const scripts: GameScriptSims = deps.simulateGameScripts(ctx.games, sims, rng, extraTeams);
  const teamCount = scripts.teams.length;
  const teamIndex = scripts.teamIndex;

  // Per-player plan: resolved script rows and output array, computed once before the sim loop.
  const gameById = new Map<string, NflGame>();
  const teamOpponent = new Map<string, string>();
  for (const g of ctx.games) {
    if (g.gameId) gameById.set(g.gameId, g);
    teamOpponent.set(g.home, g.away);
    teamOpponent.set(g.away, g.home);
  }
  interface Plan {
    id: string;
    proj: PlayerProjection | undefined;
    live: PlayerLive | undefined;
    team: number;
    opp: number;
    out: Float64Array;
  }
  const plans: Plan[] = playerIds.map((id) => {
    const proj = projectionOf(ctx, id);
    const live = liveOf(ctx, id);
    const team = proj && hasOwn(teamIndex, proj.team) ? teamIndex[proj.team] : -1;
    const opp = proj ? opponentIndex(proj, teamIndex, gameById, teamOpponent) : -1;
    return { id, proj, live, team, opp, out: new Float64Array(sims) };
  });
  // Players with no projection and no live stats score 0 every sim; they are never sampled.
  const active = plans.filter((pl) => pl.proj !== undefined || pl.live !== undefined);

  // Reusable TeamScript views, one per team, refreshed from the flat array at the start of each sim.
  const views: TeamScript[] = [];
  for (let t = 0; t < teamCount; t++) {
    views.push({ pointsFactor: 1, passFactor: 1, rushFactor: 1, pointsAllowed: 0, yardsAllowed: 0 });
  }
  const values = scripts.values;

  // 4. Sim loop: sims outer, players in sorted id order inner.
  for (let s = 0; s < sims; s++) {
    const base = s * teamCount * SCRIPT_STRIDE;
    for (let t = 0; t < teamCount; t++) {
      const o = base + t * SCRIPT_STRIDE;
      const v = views[t];
      v.pointsFactor = values[o + K_POINTS];
      v.passFactor = values[o + K_PASS];
      v.rushFactor = values[o + K_RUSH];
      v.pointsAllowed = values[o + K_PTS_ALLOW];
      v.yardsAllowed = values[o + K_YDS_ALLOW];
    }
    for (const pl of active) {
      const script = pl.team >= 0 ? views[pl.team] : undefined;
      const oppScript = pl.opp >= 0 ? views[pl.opp] : undefined;
      const stats = deps.sampleStatLine(pl.proj, script, oppScript, rng, pl.live);
      pl.out[s] = deps.scoreStatLine(stats, scoring, pl.proj?.position ?? 'UNK');
    }
  }

  // 5. Team totals: sum of each lineup's distinct starters.
  const playerPoints: Record<string, Float64Array> = {};
  for (const pl of plans) playerPoints[pl.id] = pl.out;
  const teamPoints: Record<string, Float64Array> = {};
  for (const key of keys) {
    const out = new Float64Array(sims);
    for (const p of starters.get(key) ?? []) {
      const arr = playerPoints[p];
      for (let s = 0; s < sims; s++) out[s] += arr[s];
    }
    teamPoints[key] = out;
  }

  return { sims, seed, teamPoints, playerPoints };
}

/**
 * Summarize one head-to-head from a SimResult.
 *  - pWinA = (count(A>B) + 0.5*count(|A-B| < 1e-9)) / sims; pWinB = 1 - pWinA; pTie = ties / sims.
 *  - mean/sd of each side; margin = quantiles of A-B; total = quantiles of A+B (p10/p50/p90, nearest-rank).
 *  - drivers: for every starter p in either lineup with swing (sd of playerPoints[p]) > 0.01:
 *      sort sims by p's points; top third T, bottom third Bt; impact = winRateA(T) - winRateA(Bt)
 *      (winRateA uses the same tie-half rule). Keep the 3 with largest |impact|. side = which lineup holds p
 *      (if both, 'A'). name/position from ctx.projections (fallback name = playerId, position 'UNK');
 *      status from deps.playerStatus; meanPts = mean of playerPoints[p].
 *  - meta (matchupId, week, teamA, teamB, modelVersion, asOf) copied from args.
 */
export function summarizeMatchup(
  sim: SimResult,
  keyA: string,
  keyB: string,
  lineupA: string[],
  lineupB: string[],
  ctx: WeekContext,
  meta: { matchupId: number; week: number; teamA: number; teamB: number },
  deps: PricingDeps = defaultDeps,
): MatchupPrice {
  const A = sim.teamPoints[keyA];
  const B = sim.teamPoints[keyB];
  if (!A) throw new Error(`summarizeMatchup: no team points for lineup "${keyA}"`);
  if (!B) throw new Error(`summarizeMatchup: no team points for lineup "${keyB}"`);
  const n = A.length;

  const diff = new Float64Array(n);
  const total = new Float64Array(n);
  const score = new Float64Array(n); // A's win rate per sim: 1 win, 0.5 tie, 0 loss
  let wins = 0, ties = 0, sumA = 0, sumB = 0;
  for (let i = 0; i < n; i++) {
    const d = A[i] - B[i];
    diff[i] = d;
    total[i] = A[i] + B[i];
    sumA += A[i];
    sumB += B[i];
    if (Math.abs(d) < TIE_EPS) { ties++; score[i] = 0.5; }
    else if (d > 0) { wins++; score[i] = 1; }
  }
  const pWinA = (wins + 0.5 * ties) / n;
  const meanA = sumA / n;
  const meanB = sumB / n;

  // Drivers: starters from either lineup, in sorted id order before ranking.
  const inA = new Set(uniqueStarters(lineupA));
  const inB = new Set(uniqueStarters(lineupB));
  const candidates = [...new Set([...inA, ...inB])].sort();
  const third = Math.floor(n / 3);
  const drivers: Driver[] = [];
  if (third > 0) {
    for (const p of candidates) {
      const arr = sim.playerPoints[p];
      if (!arr) continue;
      const mean = meanOf(arr);
      const swingPts = popSd(arr, mean);
      if (!(swingPts > SWING_MIN_SD)) continue;
      const proj = projectionOf(ctx, p);
      drivers.push({
        playerId: p,
        name: proj?.name ?? p,
        position: (proj?.position ?? 'UNK') as Position | 'UNK',
        side: inA.has(p) ? 'A' : 'B',
        swingPts,
        impact: tierImpact(arr, score, third),
        meanPts: mean,
        status: deps.playerStatus(proj, liveOf(ctx, p)),
      });
    }
  }
  drivers.sort((x, y) => Math.abs(y.impact) - Math.abs(x.impact) || (x.playerId < y.playerId ? -1 : x.playerId > y.playerId ? 1 : 0));

  return {
    matchupId: meta.matchupId,
    week: meta.week,
    teamA: meta.teamA,
    teamB: meta.teamB,
    pWinA,
    pWinB: 1 - pWinA,
    pTie: ties / n,
    meanA,
    meanB,
    sdA: popSd(A, meanA),
    sdB: popSd(B, meanB),
    margin: quantilesOf(diff),
    total: quantilesOf(total),
    drivers: drivers.slice(0, TOP_DRIVERS),
    sims: sim.sims,
    seed: sim.seed,
    modelVersion: ctx.modelVersion,
    asOf: ctx.asOf,
  };
}

/** Default seed: seedFrom(`${leagueId}|${week}|${ctx.asOf}|${ctx.modelVersion}`). */
export function defaultSeed(leagueId: string, week: number, ctx: WeekContext): number {
  return seedFrom(`${leagueId}|${week}|${ctx.asOf}|${ctx.modelVersion}`);
}

/**
 * Price every matchup in a league from ONE shared simulation (lineups keyed String(rosterId)).
 * Returns prices in league.matchups order. opts.sims default DEFAULT_SIMS, opts.seed default defaultSeed.
 */
export function priceLeague(league: League, ctx: WeekContext, opts: PriceOptions = {}, deps: PricingDeps = defaultDeps): MatchupPrice[] {
  const sims = opts.sims ?? DEFAULT_SIMS;
  const seed = opts.seed ?? defaultSeed(league.leagueId, league.week, ctx);

  const lineups: Record<string, string[]> = {};
  const teamById = new Map<number, FantasyTeam>();
  for (const team of league.teams) {
    lineups[String(team.rosterId)] = team.starters;
    teamById.set(team.rosterId, team);
  }
  const sim = simulateLineups(lineups, league.scoring, ctx, sims, seed, deps);

  return league.matchups.map((m) => {
    const a = teamById.get(m.teamA);
    const b = teamById.get(m.teamB);
    if (!a || !b) {
      const missing = a ? m.teamB : m.teamA;
      throw new Error(`priceLeague: matchup ${m.matchupId} references unknown roster ${missing}`);
    }
    return summarizeMatchup(
      sim,
      String(m.teamA),
      String(m.teamB),
      a.starters,
      b.starters,
      ctx,
      { matchupId: m.matchupId, week: m.week, teamA: m.teamA, teamB: m.teamB },
      deps,
    );
  });
}

/** Price two frozen lineups (a snapshot series). meta as in summarizeMatchup. */
export function priceLineups(
  lineupA: string[],
  lineupB: string[],
  scoring: ScoringRules,
  ctx: WeekContext,
  meta: { matchupId: number; week: number; teamA: number; teamB: number },
  opts: PriceOptions & { seed: number },
  deps: PricingDeps = defaultDeps,
): MatchupPrice {
  const sims = opts.sims ?? DEFAULT_SIMS;
  const sim = simulateLineups({ A: lineupA, B: lineupB }, scoring, ctx, sims, opts.seed, deps);
  return summarizeMatchup(sim, 'A', 'B', lineupA, lineupB, ctx, meta, deps);
}

/** Projected (mean simulated) points per starter for a team, for roster displays. playerId -> mean pts. */
export function meanPointsByPlayer(sim: SimResult): Record<string, number> {
  const out: Record<string, number> = {};
  for (const p of Object.keys(sim.playerPoints)) out[p] = meanOf(sim.playerPoints[p]);
  return out;
}

export type { Position };
