/**
 * WP-1 — Game-script simulator. Simulate each REAL NFL game once per sim; every fantasy matchup in every
 * league is then scored on these same paths ("simulate games, not matchups"). This is what correlates a QB
 * with his receivers and makes a RB gain when his team protects a lead.
 *
 * Owner: WP-1. Imports allowed: '@fmm/core'.
 */
import { SCRIPT_FIELDS, SCRIPT_STRIDE } from '@fmm/core';
import type { NflGame, GameScriptSims, Rng } from '@fmm/core';

export const DEFAULT_TOTAL = 44;
export const DEFAULT_SPREAD = 1.5;
/** Pregame standard deviations (points) of game total and spread. Scale by sqrt(fractionRemaining) live. */
export const TOTAL_SD = 10;
export const SPREAD_SD = 13;
/** League-average yards allowed per team-game, used to convert points to yards allowed. */
export const AVG_YARDS_PER_POINT = 15.2;
/** Clamp for every multiplier. */
export const FACTOR_MIN = 0.05;
export const FACTOR_MAX = 3;

/** Column offsets inside one TeamScript row, taken from SCRIPT_FIELDS so the layout cannot drift. */
const K_POINTS = SCRIPT_FIELDS.indexOf('pointsFactor');
const K_PASS = SCRIPT_FIELDS.indexOf('passFactor');
const K_RUSH = SCRIPT_FIELDS.indexOf('rushFactor');
const K_ALLOWED = SCRIPT_FIELDS.indexOf('pointsAllowed');
const K_YARDS = SCRIPT_FIELDS.indexOf('yardsAllowed');

/**
 * Per-game constants, precomputed once so the per-sim loop does arithmetic only.
 * `away` is -1 for a virtual league-average opponent (extra teams), which has no output row.
 */
interface SimGame {
  home: number;
  away: number;
  r: number;
  sqrtR: number;
  trem0: number;
  srem0: number;
  /** Expected remaining points for the home side ((Trem0 + Srem0) / 2) and the away side ((Trem0 - Srem0) / 2). */
  eHome: number;
  eAway: number;
  /** Expected final margin for home: (homeScore - awayScore) + Srem0. */
  expMargin: number;
  homeScore: number;
  awayScore: number;
}

function clampFactor(x: number): number {
  return x < FACTOR_MIN ? FACTOR_MIN : x > FACTOR_MAX ? FACTOR_MAX : x;
}

function statusFraction(status: NflGame['status']): number {
  switch (status) {
    case 'in_progress':
      return 0.5;
    case 'complete':
      return 0;
    default:
      return 1;
  }
}

/** Finite value, or the default when absent (null/undefined). Non-finite values are a bad input and throw. */
function finiteOr(value: number | null | undefined, fallback: number, what: string, gameId: string): number {
  const v = value ?? fallback;
  if (!Number.isFinite(v)) throw new RangeError(`${what} for game ${gameId} must be finite, got ${String(value)}`);
  return v;
}

/**
 * Write one team's TeamScript row. `pts` is the team's remaining points, `expPts` its expected remaining
 * points, `z` its lead z-score, `allowed` the opponent's final points.
 */
function writeRow(
  values: Float64Array,
  base: number,
  pts: number,
  expPts: number,
  z: number,
  allowed: number,
): void {
  const pf = expPts > 0.5 ? clampFactor(pts / expPts) : 1;
  values[base + K_POINTS] = pf;
  values[base + K_RUSH] = clampFactor(pf * (1 + 0.12 * z));
  values[base + K_PASS] = clampFactor(pf * (1 - 0.08 * z));
  values[base + K_ALLOWED] = allowed;
  values[base + K_YARDS] = Math.max(0, allowed * AVG_YARDS_PER_POINT + 120);
}

/**
 * Simulate game scripts.
 *
 * For each sim and each game g (home H, away A):
 *  - r = fractionRemaining(g) (use g.fractionRemaining, else status: scheduled=1, in_progress=0.5, complete=0).
 *  - expected total T0 = g.impliedTotal ?? DEFAULT_TOTAL; expected spread S0 = g.spread ?? DEFAULT_SPREAD.
 *  - Remaining-points expectation: Trem0 = T0 * r, Srem0 = S0 * r.
 *  - Draw Trem = Trem0 + TOTAL_SD*sqrt(r)*z1, Srem = Srem0 + SPREAD_SD*sqrt(r)*z2 (z independent normals).
 *  - Remaining team points: hRem = max(0,(Trem+Srem)/2), aRem = max(0,(Trem-Srem)/2).
 *  - Final team points: hFinal = (g.homeScore ?? 0) + hRem, aFinal likewise.
 *  - pointsFactor for a team = its REMAINING points / its expected remaining points ((Trem0±Srem0)/2),
 *    clamped to [FACTOR_MIN, FACTOR_MAX]; if expected remaining points <= 0.5 (game over) use 1.
 *    (Player samplers multiply a player's remaining expected stats by this factor.)
 *  - Lead z for a team: zLead = (team's (final points - opponent final points) - expected final margin) / SPREAD_SD
 *    where expected final margin = (homeScore-awayScore at r) + Srem0 for home (negated for away).
 *    rushFactor = clamp(pointsFactor * (1 + 0.12 * zLead)); passFactor = clamp(pointsFactor * (1 - 0.08 * zLead)).
 *  - pointsAllowed = opponent's FINAL points; yardsAllowed = pointsAllowed * AVG_YARDS_PER_POINT + 120 (floor 0).
 *  - When r === 0 all factors are 1 and points are the final score.
 *
 * Teams in `extraTeams` that are not in any game (unknown schedule) get their own independent game vs a
 * league-average opponent with T0 = DEFAULT_TOTAL, S0 = 0, r = 1, and appear in `teams` like any other team.
 *
 * Output layout: see GameScriptSims / SCRIPT_FIELDS in @fmm/core. `teams` lists every team exactly once
 * (games first in input order, home then away, then extraTeams not already present).
 *
 * Must be deterministic for a given rng state and must not allocate per sim (one Float64Array).
 * Performance target: 16 games x 10,000 sims in under 50 ms in Node.
 */
export function simulateGameScripts(
  games: NflGame[],
  sims: number,
  rng: Rng,
  extraTeams: string[] = [],
): GameScriptSims {
  if (!Number.isInteger(sims) || sims < 0) {
    throw new RangeError(`sims must be a non-negative integer, got ${sims}`);
  }

  const teams: string[] = [];
  const indexOf = new Map<string, number>();
  const addTeam = (abbr: string): number => {
    const existing = indexOf.get(abbr);
    if (existing !== undefined) return existing;
    const idx = teams.length;
    teams.push(abbr);
    indexOf.set(abbr, idx);
    return idx;
  };

  const simGames: SimGame[] = [];
  for (const g of games) {
    if (g.home === g.away) throw new RangeError(`game ${g.gameId} lists ${g.home} on both sides`);
    if (indexOf.has(g.home) || indexOf.has(g.away)) {
      throw new RangeError(`game ${g.gameId} repeats a team already scheduled (${g.home} / ${g.away})`);
    }
    const r = gameFractionRemaining(g);
    const t0 = finiteOr(g.impliedTotal, DEFAULT_TOTAL, 'impliedTotal', g.gameId);
    const s0 = finiteOr(g.spread, DEFAULT_SPREAD, 'spread', g.gameId);
    const homeScore = finiteOr(g.homeScore, 0, 'homeScore', g.gameId);
    const awayScore = finiteOr(g.awayScore, 0, 'awayScore', g.gameId);
    const trem0 = t0 * r;
    const srem0 = s0 * r;
    simGames.push({
      home: addTeam(g.home),
      away: addTeam(g.away),
      r,
      sqrtR: Math.sqrt(r),
      trem0,
      srem0,
      eHome: (trem0 + srem0) / 2,
      eAway: (trem0 - srem0) / 2,
      expMargin: homeScore - awayScore + srem0,
      homeScore,
      awayScore,
    });
  }

  // Extra teams with no game: each gets its own virtual game vs a league-average opponent (no output row).
  for (const team of extraTeams) {
    if (indexOf.has(team)) continue;
    const idx = addTeam(team);
    simGames.push({
      home: idx,
      away: -1,
      r: 1,
      sqrtR: 1,
      trem0: DEFAULT_TOTAL,
      srem0: 0,
      eHome: DEFAULT_TOTAL / 2,
      eAway: DEFAULT_TOTAL / 2,
      expMargin: 0,
      homeScore: 0,
      awayScore: 0,
    });
  }

  const nTeams = teams.length;
  const nGames = simGames.length;
  const values = new Float64Array(sims * nTeams * SCRIPT_STRIDE);

  for (let sim = 0; sim < sims; sim++) {
    const simBase = sim * nTeams * SCRIPT_STRIDE;
    for (let gi = 0; gi < nGames; gi++) {
      const sg = simGames[gi];
      // Always two draws per game so the RNG stream does not depend on which games are finished.
      const z1 = rng.normal();
      const z2 = rng.normal();
      const trem = sg.trem0 + TOTAL_SD * sg.sqrtR * z1;
      const srem = sg.srem0 + SPREAD_SD * sg.sqrtR * z2;
      const hRem = Math.max(0, (trem + srem) / 2);
      const aRem = Math.max(0, (trem - srem) / 2);
      const hFinal = sg.homeScore + hRem;
      const aFinal = sg.awayScore + aRem;
      // Finished games have no remaining play, so the lead z is 0 and the factors stay exactly 1.
      const zHome = sg.r > 0 ? (hFinal - aFinal - sg.expMargin) / SPREAD_SD : 0;

      writeRow(values, simBase + sg.home * SCRIPT_STRIDE, hRem, sg.eHome, zHome, aFinal);
      if (sg.away >= 0) {
        writeRow(values, simBase + sg.away * SCRIPT_STRIDE, aRem, sg.eAway, -zHome, hFinal);
      }
    }
  }

  // The lead term is correlated with a team's own points, which tilts the averages (about +3% rushing and -2%
  // passing for a pick'em game). Rescale so pass and rush factors average the same as the points factor:
  // game scripts then reshuffle production between run and pass without biasing either projection.
  if (sims > 0) {
    for (let t = 0; t < nTeams; t++) {
      let sp = 0, sPass = 0, sRush = 0;
      for (let sim = 0; sim < sims; sim++) {
        const o = (sim * nTeams + t) * SCRIPT_STRIDE;
        sp += values[o]; sPass += values[o + 1]; sRush += values[o + 2];
      }
      const kPass = sPass > 0 ? sp / sPass : 1;
      const kRush = sRush > 0 ? sp / sRush : 1;
      if (Math.abs(kPass - 1) < 1e-12 && Math.abs(kRush - 1) < 1e-12) continue;
      for (let sim = 0; sim < sims; sim++) {
        const o = (sim * nTeams + t) * SCRIPT_STRIDE;
        values[o + 1] = Math.min(FACTOR_MAX, Math.max(FACTOR_MIN, values[o + 1] * kPass));
        values[o + 2] = Math.min(FACTOR_MAX, Math.max(FACTOR_MIN, values[o + 2] * kRush));
      }
    }
  }

  const teamIndex: Record<string, number> = Object.fromEntries(indexOf);
  return { teams, teamIndex, sims, values };
}

/** fractionRemaining for a game per the rule above. */
export function gameFractionRemaining(g: NflGame): number {
  const f = g.fractionRemaining;
  if (typeof f === 'number' && Number.isFinite(f)) return Math.min(1, Math.max(0, f));
  return statusFraction(g.status);
}
