/**
 * WP-17 — Backtest: how good is the number? Uses past weeks' projections and actual stats.
 *  1. Player level: is each player's simulated distribution the right width? (PIT histogram, 80% interval coverage)
 *  2. Matchup level: synthetic leagues drafted from real players each week, priced pregame, scored on actual stats:
 *     Brier, log loss, reliability bins. "When we said 70%, teams won X%".
 * Pure + deterministic (seeded). Runs in a browser worker on the Model page.
 * Owner: WP-17. Imports allowed: '@fmm/core', './gameScript', './players', './scoring', './pricing', './calibration'.
 */
import type { PlayerProjection, NflGame, ScoringRules, Position, StatLine, TeamScript, WeekContext, Rng } from '@fmm/core';
import { POSITIONS, SCRIPT_FIELDS, SCRIPT_STRIDE, createRng, seedFrom } from '@fmm/core';
import { simulateGameScripts } from './gameScript';
import { sampleStatLine } from './players';
import { scoreStatLine } from './scoring';
import { MODEL_VERSION, priceLineups } from './pricing';
import { brierScore, logLoss, reliabilityBins } from './calibration';
import type { Forecast, ReliabilityBin } from './calibration';

export interface BacktestWeek {
  week: number;
  games: NflGame[];
  projections: Record<string, PlayerProjection>;
  /** Actual full-week raw stat lines for players who played (cleanStatLine applied). Missing = did not play (0). */
  actual: Record<string, StatLine>;
}

export interface PlayerCalibration {
  position: Position | 'ALL';
  n: number;
  /** Mean of (actual - simulated mean) points. Positive = projections too low. */
  bias: number;
  /** Share of actual results inside the simulated 10th-90th percentile range. Target 0.80. */
  coverage80: number;
  /** 10-bin PIT histogram as shares of observations (each bin = share of player-weeks, sums to 1; PIT = share of sims <= actual, randomized on ties). Flat = well calibrated. */
  pit: number[];
  /** Mean absolute error of the simulated mean vs actual points. */
  mae: number;
}

export interface MatchupForecastRow { week: number; league: number; matchup: number; pA: number; pointsA: number; pointsB: number; outcome: 0 | 0.5 | 1 }

export interface BacktestResult {
  weeks: number[];
  players: PlayerCalibration[];
  forecasts: MatchupForecastRow[];
  brier: number;
  logLoss: number;
  /** Brier of always saying 50%. */
  baselineBrier: number;
  bins: ReliabilityBin[];
  /** Share of matchups the favorite (pA > 0.5) won. Ties count half. Favorite = A when pA > 0.5, B when pA < 0.5. */
  favoriteWinRate: number;
  simsPerPlayer: number;
  simsPerMatchup: number;
}

export interface BacktestOptions {
  scoring: ScoringRules;
  /** Default 2000. */
  simsPerPlayer?: number;
  /** Default 2000. */
  simsPerMatchup?: number;
  /** Synthetic 12-team leagues per week. Default 8. */
  leaguesPerWeek?: number;
  seed?: number;
  /** Called with progress 0..1 (optional). */
  onProgress?: (p: number) => void;
}

const DEFAULT_SIMS = 2000;
const DEFAULT_LEAGUES = 8;
const DEFAULT_SEED = seedFrom('fmm-backtest-v1');
const TEAMS_PER_LEAGUE = 12;
const PIT_BINS = 10;
const DRAFT_TOP_K = 3;

/** Starter slots in roster_positions order. */
const SLOT_COUNT = 9;
const FLEX_SLOT = 6;
/** Slot indices a position fills before FLEX, in order. */
const DEDICATED_SLOTS: Readonly<Record<Position, readonly number[]>> = {
  QB: [0], RB: [1, 2], WR: [3, 4], TE: [5], K: [7], DEF: [8],
};
const FLEX_POSITIONS: ReadonlySet<Position> = new Set<Position>(['RB', 'WR', 'TE']);

const K_POINTS = SCRIPT_FIELDS.indexOf('pointsFactor');
const K_PASS = SCRIPT_FIELDS.indexOf('passFactor');
const K_RUSH = SCRIPT_FIELDS.indexOf('rushFactor');
const K_PTS_ALLOW = SCRIPT_FIELDS.indexOf('pointsAllowed');
const K_YDS_ALLOW = SCRIPT_FIELDS.indexOf('yardsAllowed');

function hasOwn(rec: object, key: string): boolean {
  return Object.prototype.hasOwnProperty.call(rec, key);
}

function round2(x: number): number {
  return Math.round(x * 100) / 100;
}

/** First open slot a player of this position fills (dedicated first, then FLEX), or -1. */
function slotFor(open: boolean[], pos: Position): number {
  for (const i of DEDICATED_SLOTS[pos]) if (open[i]) return i;
  if (FLEX_POSITIONS.has(pos) && open[FLEX_SLOT]) return FLEX_SLOT;
  return -1;
}

/**
 * Synthetic snake draft for one league: candidates = players with projections, ranked by projected points
 * (scoreStatLine of proj.mean under `scoring`). 12 teams fill QB,RB,RB,WR,WR,TE,FLEX(RB/WR/TE),K,DEF starters only.
 * To vary leagues, each team's pick is drawn uniformly from the top 3 remaining eligible players (rng). Returns
 * 12 starter lists. Requires enough players; if a slot can't be filled leave it out.
 */
export function syntheticDraft(projections: Record<string, PlayerProjection>, scoring: ScoringRules, seed: number): string[][] {
  const rng: Rng = createRng(seed);

  // Pool: projected players with positive projected points, best first (ties by id for determinism).
  const pool: { id: string; pos: Position; value: number }[] = [];
  for (const id of Object.keys(projections).sort()) {
    if (!hasOwn(projections, id)) continue;
    const proj = projections[id];
    if (!proj || !POSITIONS.includes(proj.position)) continue;
    const value = scoreStatLine(proj.mean ?? {}, scoring, proj.position);
    if (value > 0) pool.push({ id, pos: proj.position, value });
  }
  pool.sort((a, b) => b.value - a.value || (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));

  const taken = new Uint8Array(pool.length);
  const open: boolean[][] = [];
  const lineups: (string | undefined)[][] = [];
  for (let t = 0; t < TEAMS_PER_LEAGUE; t++) {
    open.push(new Array<boolean>(SLOT_COUNT).fill(true));
    lineups.push(new Array<string | undefined>(SLOT_COUNT).fill(undefined));
  }

  // Snake: round r runs teams 0..11 when r is even, 11..0 when odd. One pick per team per round.
  const rounds = SLOT_COUNT;
  const eligible: number[] = [];
  for (let round = 0; round < rounds; round++) {
    for (let k = 0; k < TEAMS_PER_LEAGUE; k++) {
      const t = round % 2 === 0 ? k : TEAMS_PER_LEAGUE - 1 - k;
      eligible.length = 0;
      for (let i = 0; i < pool.length && eligible.length < DRAFT_TOP_K; i++) {
        if (taken[i]) continue;
        if (slotFor(open[t], pool[i].pos) >= 0) eligible.push(i);
      }
      if (eligible.length === 0) continue;
      const pick = eligible[Math.min(eligible.length - 1, Math.floor(rng.next() * eligible.length))];
      const slot = slotFor(open[t], pool[pick].pos);
      open[t][slot] = false;
      lineups[t][slot] = pool[pick].id;
      taken[pick] = 1;
    }
  }

  return lineups.map((row) => row.filter((id): id is string => id !== undefined));
}

/** Games stripped to their pregame state: no live score, not started. Keeps the backtest from seeing results. */
function pregameGames(games: NflGame[]): NflGame[] {
  return games.map((g) => ({
    gameId: g.gameId,
    week: g.week,
    home: g.home,
    away: g.away,
    kickoff: g.kickoff,
    status: 'scheduled',
    impliedTotal: g.impliedTotal,
    spread: g.spread,
    fractionRemaining: 1,
  }));
}

/** Opponent abbreviation for a projected player: proj.opponent, else the other side of its game, else undefined. */
function opponentName(proj: PlayerProjection, games: NflGame[]): string | undefined {
  if (proj.opponent) return proj.opponent;
  for (const g of games) {
    if (proj.gameId && g.gameId !== proj.gameId) continue;
    if (g.home === proj.team) return g.away;
    if (g.away === proj.team) return g.home;
  }
  return undefined;
}

interface Accumulator { n: number; biasSum: number; absSum: number; covered: number; pit: number[] }

function record(acc: Map<string, Accumulator>, key: string, bias: number, absErr: number, covered: boolean, bin: number): void {
  let a = acc.get(key);
  if (!a) {
    a = { n: 0, biasSum: 0, absSum: 0, covered: 0, pit: new Array<number>(PIT_BINS).fill(0) };
    acc.set(key, a);
  }
  a.n++;
  a.biasSum += bias;
  a.absSum += absErr;
  if (covered) a.covered++;
  a.pit[bin]++;
}

/**
 * Player level for one week: one shared game-script simulation, then each player who has both a projection and
 * an actual line gets simsPerPlayer simulated point totals. Compares them with the actual points.
 */
function playerPass(
  week: BacktestWeek,
  scoring: ScoringRules,
  sims: number,
  rng: Rng,
  pitRng: Rng,
  acc: Map<string, Accumulator>,
): void {
  const ids = Object.keys(week.actual).filter((id) => hasOwn(week.projections, id)).sort();
  if (ids.length === 0) return;
  const games = pregameGames(week.games);

  // Players whose team has no game this week get a virtual opponent, as in pricing.
  const gameTeams = new Set<string>();
  for (const g of games) { gameTeams.add(g.home); gameTeams.add(g.away); }
  const extraTeams: string[] = [];
  const extraSeen = new Set<string>();
  for (const id of ids) {
    const team = week.projections[id].team;
    if (gameTeams.has(team) || extraSeen.has(team)) continue;
    extraSeen.add(team);
    extraTeams.push(team);
  }

  const scripts = simulateGameScripts(games, sims, rng, extraTeams);
  const nT = scripts.teams.length;
  const nP = ids.length;

  interface Plan { proj: PlayerProjection; pos: Position; team: number; opp: number; actual: number }
  const plans: Plan[] = ids.map((id) => {
    const proj = week.projections[id];
    const oppName = opponentName(proj, games);
    const opp = oppName !== undefined && hasOwn(scripts.teamIndex, oppName) ? scripts.teamIndex[oppName] : -1;
    const actualLine = week.actual[id];
    return {
      proj,
      pos: proj.position,
      team: scripts.teamIndex[proj.team],
      opp,
      actual: scoreStatLine(actualLine, scoring, proj.position),
    };
  });

  // Player-major layout: pts[j * sims + s] is player j's points in sim s.
  const pts = new Float64Array(nP * sims);
  const views: TeamScript[] = [];
  for (let t = 0; t < nT; t++) {
    views.push({ pointsFactor: 1, passFactor: 1, rushFactor: 1, pointsAllowed: 0, yardsAllowed: 0 });
  }
  const vals = scripts.values;
  for (let s = 0; s < sims; s++) {
    const base = s * nT * SCRIPT_STRIDE;
    for (let t = 0; t < nT; t++) {
      const o = base + t * SCRIPT_STRIDE;
      const v = views[t];
      v.pointsFactor = vals[o + K_POINTS];
      v.passFactor = vals[o + K_PASS];
      v.rushFactor = vals[o + K_RUSH];
      v.pointsAllowed = vals[o + K_PTS_ALLOW];
      v.yardsAllowed = vals[o + K_YDS_ALLOW];
    }
    for (let j = 0; j < nP; j++) {
      const pl = plans[j];
      const stats = sampleStatLine(pl.proj, views[pl.team], pl.opp >= 0 ? views[pl.opp] : undefined, rng);
      pts[j * sims + s] = scoreStatLine(stats, scoring, pl.pos);
    }
  }

  // Lower and upper 80% bounds per player: nearest-rank 10th and 90th percentiles.
  const sorted = new Float64Array(sims);
  const lo = Math.floor(0.1 * sims);
  const hi = Math.min(sims - 1, Math.ceil(0.9 * sims) - 1);
  for (let j = 0; j < nP; j++) {
    const off = j * sims;
    const pl = plans[j];
    let sum = 0;
    for (let s = 0; s < sims; s++) sum += pts[off + s];
    const mean = sum / sims;

    sorted.set(pts.subarray(off, off + sims));
    sorted.sort();
    const covered = pl.actual >= sorted[lo] && pl.actual <= sorted[hi];

    // PIT: share of sims strictly below the actual, plus a seeded uniform share of the exact ties.
    let less = 0, equal = 0;
    for (let s = 0; s < sims; s++) {
      const v = pts[off + s];
      if (v < pl.actual) less++;
      else if (v === pl.actual) equal++;
    }
    const pit = (less + pitRng.next() * equal) / sims;
    const bin = Math.min(PIT_BINS - 1, Math.floor(pit * PIT_BINS));

    const bias = pl.actual - mean;
    const absErr = Math.abs(bias);
    record(acc, 'ALL', bias, absErr, covered, bin);
    record(acc, pl.pos, bias, absErr, covered, bin);
  }
}

/**
 * Matchup level for one week: synthetic leagues drafted from the week's projections, each pair of teams priced
 * pregame with priceLineups, then scored on the actual points (a missing player scores 0).
 */
function matchupPass(
  week: BacktestWeek,
  scoring: ScoringRules,
  leagues: number,
  sims: number,
  seed: number,
  out: MatchupForecastRow[],
): void {
  if (leagues <= 0) return;
  const ctx: WeekContext = {
    season: 'backtest',
    week: week.week,
    games: pregameGames(week.games),
    projections: week.projections,
    asOf: `backtest-week-${week.week}`,
    modelVersion: MODEL_VERSION,
  };

  const actualCache = new Map<string, number>();
  const actualPoints = (id: string): number => {
    let v = actualCache.get(id);
    if (v === undefined) {
      const line = hasOwn(week.actual, id) ? week.actual[id] : undefined;
      const pos = hasOwn(week.projections, id) ? week.projections[id].position : 'UNK';
      v = line ? scoreStatLine(line, scoring, pos) : 0;
      actualCache.set(id, v);
    }
    return v;
  };

  for (let league = 0; league < leagues; league++) {
    const lineups = syntheticDraft(week.projections, scoring, seedFrom(`${seed}|draft|${week.week}|${league}`));
    const pairs = Math.floor(lineups.length / 2);
    for (let m = 0; m < pairs; m++) {
      const a = lineups[2 * m];
      const b = lineups[2 * m + 1];
      const price = priceLineups(
        a,
        b,
        scoring,
        ctx,
        { matchupId: league * pairs + m + 1, week: week.week, teamA: 2 * m + 1, teamB: 2 * m + 2 },
        { sims, seed: seedFrom(`${seed}|match|${week.week}|${league}|${m}`) },
      );

      let sumA = 0, sumB = 0;
      for (const id of a) sumA += actualPoints(id);
      for (const id of b) sumB += actualPoints(id);
      const centsA = Math.round(sumA * 100);
      const centsB = Math.round(sumB * 100);
      const outcome: 0 | 0.5 | 1 = centsA > centsB ? 1 : centsA < centsB ? 0 : 0.5;

      out.push({
        week: week.week,
        league,
        matchup: m,
        pA: Math.min(1, Math.max(0, price.pWinA)),
        pointsA: round2(sumA),
        pointsB: round2(sumB),
        outcome,
      });
    }
  }
}

function assertPositiveInt(name: string, v: number): void {
  if (!Number.isInteger(v) || v < 1) throw new RangeError(`runBacktest: ${name} must be a positive integer, got ${v}`);
}

/**
 * Run the full backtest. Player level: for each week, one simulateGameScripts(games, simsPerPlayer), then for each
 * projected player sample simsPerPlayer stat lines -> points; compare with scoreStatLine(actual[p] ?? {}) for players
 * who appear in `actual` (skip players with no actual line — unknown whether they played). Matchup level: per week
 * leaguesPerWeek syntheticDraft leagues, pair teams (1v2, 3v4, ...), price with priceLineups (simsPerMatchup, seeded),
 * outcome from summed actual points (missing player = 0). Metrics via ./calibration.
 */
export function runBacktest(weeks: BacktestWeek[], opts: BacktestOptions): BacktestResult {
  const simsPerPlayer = opts.simsPerPlayer ?? DEFAULT_SIMS;
  const simsPerMatchup = opts.simsPerMatchup ?? DEFAULT_SIMS;
  const leaguesPerWeek = opts.leaguesPerWeek ?? DEFAULT_LEAGUES;
  const seed = opts.seed ?? DEFAULT_SEED;
  assertPositiveInt('simsPerPlayer', simsPerPlayer);
  assertPositiveInt('simsPerMatchup', simsPerMatchup);
  if (!Number.isInteger(leaguesPerWeek) || leaguesPerWeek < 0) {
    throw new RangeError(`runBacktest: leaguesPerWeek must be a non-negative integer, got ${leaguesPerWeek}`);
  }
  const report = opts.onProgress ?? (() => undefined);

  const acc = new Map<string, Accumulator>();
  const forecasts: MatchupForecastRow[] = [];
  const W = weeks.length;
  if (W === 0) report(1);

  weeks.forEach((week, wi) => {
    const playerRng = createRng(seedFrom(`${seed}|players|${week.week}`));
    const pitRng = createRng(seedFrom(`${seed}|pit|${week.week}`));
    playerPass(week, opts.scoring, simsPerPlayer, playerRng, pitRng, acc);
    report((wi + 0.5) / W);
    matchupPass(week, opts.scoring, leaguesPerWeek, simsPerMatchup, seed, forecasts);
    report((wi + 1) / W);
  });

  const players: PlayerCalibration[] = [];
  for (const key of ['ALL', ...POSITIONS] as const) {
    const a = acc.get(key);
    if (!a || a.n === 0) continue;
    players.push({
      position: key,
      n: a.n,
      bias: a.biasSum / a.n,
      coverage80: a.covered / a.n,
      pit: a.pit.map((c) => c / a.n),
      mae: a.absSum / a.n,
    });
  }

  const fs: Forecast[] = forecasts.map((f) => ({ p: f.pA, outcome: f.outcome }));
  const baselineBrier = brierScore(fs.map((f) => ({ p: 0.5, outcome: f.outcome })));

  let favN = 0, favSum = 0;
  for (const f of forecasts) {
    if (f.pA > 0.5) { favN++; favSum += f.outcome; }
    else if (f.pA < 0.5) { favN++; favSum += 1 - f.outcome; }
  }

  return {
    weeks: weeks.map((w) => w.week),
    players,
    forecasts,
    brier: brierScore(fs),
    logLoss: logLoss(fs),
    baselineBrier,
    bins: reliabilityBins(fs, 10),
    favoriteWinRate: favN > 0 ? favSum / favN : NaN,
    simsPerPlayer,
    simsPerMatchup,
  };
}
