/**
 * Shared domain types for Fantasy Matchup Market. THIS FILE IS THE CONTRACT.
 * Owner: Commander. Builders import from '@fmm/core' and never edit this file.
 */

export type Position = 'QB' | 'RB' | 'WR' | 'TE' | 'K' | 'DEF';
export const POSITIONS: readonly Position[] = ['QB', 'RB', 'WR', 'TE', 'K', 'DEF'];

/** Raw stat line keyed by Sleeper stat keys, e.g. { pass_yd: 257.8, pass_td: 1.33 }. */
export type StatLine = Record<string, number>;

/** Sleeper `scoring_settings`: stat key -> fantasy points per unit (e.g. rec: 1, pass_yd: 0.04). */
export type ScoringRules = Record<string, number>;

export type GameStatus = 'scheduled' | 'in_progress' | 'complete';

/** One real NFL game in the week. Teams are NFL abbreviations ("BUF", "KC", "DEF" ids equal team abbr). */
export interface NflGame {
  gameId: string;
  week: number;
  home: string;
  away: string;
  /** ISO timestamp of kickoff if known. */
  kickoff?: string;
  status: GameStatus;
  /** Expected combined points (Vegas-style total). Default 44 when unknown. */
  impliedTotal?: number;
  /** Expected home minus away points. Positive = home favored. Default 1.5 (home edge) when unknown. */
  spread?: number;
  /** Live score so far (in_progress or complete). */
  homeScore?: number;
  awayScore?: number;
  /** Share of the game still to play: 1 = not started, 0 = finished. Derived from status when absent. */
  fractionRemaining?: number;
}

export type ProjectionSource = 'sleeper-weekly' | 'heuristic' | 'demo';

/** A player's projection for one full game of the week. */
export interface PlayerProjection {
  playerId: string;
  name: string;
  position: Position;
  /** NFL team abbreviation. For DEF, playerId === team. */
  team: string;
  opponent?: string | null;
  gameId?: string | null;
  injuryStatus?: string | null;
  /** Expected raw stats for a full game. Only keys in STAT_CATALOG are used by the simulator. */
  mean: StatLine;
  source: ProjectionSource;
}

/** Live state of a player during the week. */
export interface PlayerLive {
  playerId: string;
  /** Stats already recorded this week. */
  actual: StatLine;
  /** Share of this player's game still to play: 1 = not started, 0 = finished. */
  fractionRemaining: number;
}

export interface FantasyTeam {
  /** Sleeper roster_id (1..N). Unique within a league. */
  rosterId: number;
  ownerId: string | null;
  /** Team name shown in UI (metadata.team_name, else display_name, else "Team N"). */
  name: string;
  /** Manager display name, e.g. "Dave". */
  managerName: string;
  avatar?: string | null;
  /** Starter player ids in roster_positions order. Empty slots are "0" or "" and score 0. */
  starters: string[];
  /** All rostered player ids (starters + bench + reserve). */
  players: string[];
  record?: { wins: number; losses: number; ties: number };
}

export interface Matchup {
  /** Sleeper matchup_id. */
  matchupId: number;
  week: number;
  /** rosterId of team A (lower roster id) and team B. */
  teamA: number;
  teamB: number;
  /** Official points so far from the platform, if known. */
  pointsA?: number;
  pointsB?: number;
}

export type Platform = 'sleeper' | 'demo';

export interface League {
  platform: Platform;
  leagueId: string;
  name: string;
  season: string;
  week: number;
  scoring: ScoringRules;
  /** e.g. ["QB","RB","RB","WR","WR","TE","FLEX","K","DEF","BN",...] */
  rosterPositions: string[];
  teams: FantasyTeam[];
  matchups: Matchup[];
  /** rosterId of the viewing user, if known. */
  myRosterId?: number | null;
  /** True for the built-in demo league: UI must show the "Sample league" badge. */
  isSample?: boolean;
}

/** Everything the engine needs about the real-world week, independent of any fantasy league. */
export interface WeekContext {
  season: string;
  week: number;
  games: NflGame[];
  /** Keyed by playerId. A rostered player missing here projects to 0 (unknown/bye). */
  projections: Record<string, PlayerProjection>;
  /** Live stats keyed by playerId. Missing = not started. */
  live?: Record<string, PlayerLive>;
  /** ISO timestamp the inputs describe. */
  asOf: string;
  /** e.g. "fmm-sim-0.1 (sleeper-weekly)". Stamped on every price. */
  modelVersion: string;
}

/** Per-sim multipliers for one NFL team relative to its projection. 1.0 = exactly as projected. */
export interface TeamScript {
  pointsFactor: number;
  passFactor: number;
  rushFactor: number;
  /** Points this team allows (its opponent's points) for DEF scoring, absolute points. */
  pointsAllowed: number;
  /** Yards this team allows for DEF scoring, absolute yards. */
  yardsAllowed: number;
}

/**
 * Output of simulateGameScripts: for every team and sim, a TeamScript.
 * Stored flat for speed: values[(sim * teams.length + t) * SCRIPT_STRIDE + k], k in SCRIPT_FIELDS order.
 */
export interface GameScriptSims {
  teams: string[];
  teamIndex: Record<string, number>;
  sims: number;
  values: Float64Array;
}
export const SCRIPT_FIELDS = ['pointsFactor', 'passFactor', 'rushFactor', 'pointsAllowed', 'yardsAllowed'] as const;
export const SCRIPT_STRIDE = SCRIPT_FIELDS.length;

export interface PriceOptions {
  /** Number of simulated weeks. Default 10000. */
  sims?: number;
  /** RNG seed. Default seedFrom(`${leagueId}|${week}|${asOf}|${modelVersion}`) so the same inputs always give the same number. */
  seed?: number;
}

export interface Quantiles { p10: number; p50: number; p90: number }

/** One of the top players driving a matchup ("what moves this"). */
export interface Driver {
  playerId: string;
  name: string;
  position: Position | 'UNK';
  side: 'A' | 'B';
  /** Standard deviation of this player's simulated fantasy points (shown as "±X pts"). */
  swingPts: number;
  /** pWinA when this player lands in his top third minus pWinA in his bottom third. Positive helps A. */
  impact: number;
  /** Mean simulated points (including actual points already scored). */
  meanPts: number;
  /** 'final' | 'live' | 'upcoming' | 'out' */
  status: 'final' | 'live' | 'upcoming' | 'out';
}

export interface MatchupPrice {
  matchupId: number;
  week: number;
  teamA: number;
  teamB: number;
  /** P(A wins) with ties counted half: P(A>B) + 0.5 P(A=B). pWinA + pWinB === 1. */
  pWinA: number;
  pWinB: number;
  pTie: number;
  meanA: number;
  meanB: number;
  sdA: number;
  sdB: number;
  /** Distribution of A minus B points. */
  margin: Quantiles;
  /** Distribution of A plus B points. */
  total: Quantiles;
  /** Top 3 drivers by |impact|. */
  drivers: Driver[];
  sims: number;
  seed: number;
  modelVersion: string;
  asOf: string;
}

/** Output of the shared simulation: per-key Float64Array of length sims. */
export interface SimResult {
  sims: number;
  seed: number;
  /** Team total fantasy points per sim, keyed by lineup key (e.g. String(rosterId)). */
  teamPoints: Record<string, Float64Array>;
  /** Player fantasy points per sim, keyed by playerId (only players in some lineup). */
  playerPoints: Record<string, Float64Array>;
}

export type Side = 'YES' | 'NO';
