/**
 * Seeded, fast, deterministic RNG (sfc32 seeded by splitmix32). Same seed -> same sequence on every
 * platform, so the probability a user sees is exactly the one the house prices from.
 * Owner: Commander.
 */
export interface Rng {
  /** Uniform in (0, 1), never exactly 0 or 1. */
  next(): number;
  /** Standard normal N(0, 1). */
  normal(): number;
  /** Gamma(shape k > 0, scale theta > 0); mean k*theta. Returns 0 when k <= 0 or theta <= 0. */
  gamma(shape: number, scale: number): number;
  /** Poisson(lambda >= 0). Returns 0 when lambda <= 0. */
  poisson(lambda: number): number;
  /** Gamma draw with the given mean and coefficient of variation (sd/mean). Returns 0 when mean <= 0. */
  gammaMeanCv(mean: number, cv: number): number;
}

function splitmix32(a: number): () => number {
  return () => {
    a |= 0;
    a = (a + 0x9e3779b9) | 0;
    let t = a ^ (a >>> 16);
    t = Math.imul(t, 0x21f0aaad);
    t = t ^ (t >>> 15);
    t = Math.imul(t, 0x735a2d97);
    return ((t = t ^ (t >>> 15)) >>> 0);
  };
}

export function createRng(seed: number): Rng {
  const sm = splitmix32(seed >>> 0);
  let a = sm(), b = sm(), c = sm(), d = sm();
  const u32 = (): number => {
    a >>>= 0; b >>>= 0; c >>>= 0; d >>>= 0;
    let t = (a + b) | 0;
    a = b ^ (b >>> 9);
    b = (c + (c << 3)) | 0;
    c = (c << 21) | (c >>> 11);
    d = (d + 1) | 0;
    t = (t + d) | 0;
    c = (c + t) | 0;
    return t >>> 0;
  };
  for (let i = 0; i < 12; i++) u32();
  const next = (): number => (u32() + 0.5) / 4294967296;
  let spare: number | null = null;
  const normal = (): number => {
    if (spare !== null) { const s = spare; spare = null; return s; }
    let u = 0, v = 0, s = 0;
    do { u = next() * 2 - 1; v = next() * 2 - 1; s = u * u + v * v; } while (s >= 1 || s === 0);
    const m = Math.sqrt((-2 * Math.log(s)) / s);
    spare = v * m;
    return u * m;
  };
  const gamma = (k: number, theta: number): number => {
    if (!(k > 0) || !(theta > 0)) return 0;
    if (k < 1) {
      const g = gamma(k + 1, 1);
      return g * Math.pow(next(), 1 / k) * theta;
    }
    const dd = k - 1 / 3;
    const cc = 1 / Math.sqrt(9 * dd);
    for (;;) {
      let x: number, v: number;
      do { x = normal(); v = 1 + cc * x; } while (v <= 0);
      v = v * v * v;
      const u = next();
      if (u < 1 - 0.0331 * x * x * x * x) return dd * v * theta;
      if (Math.log(u) < 0.5 * x * x + dd * (1 - v + Math.log(v))) return dd * v * theta;
    }
  };
  const poisson = (lambda: number): number => {
    if (!(lambda > 0)) return 0;
    if (lambda < 12) {
      const L = Math.exp(-lambda);
      let k = 0, p = 1;
      do { k++; p *= next(); } while (p > L);
      return k - 1;
    }
    // Normal approximation with continuity correction for large lambda.
    return Math.max(0, Math.round(lambda + Math.sqrt(lambda) * normal()));
  };
  const gammaMeanCv = (mean: number, cv: number): number => {
    if (!(mean > 0)) return 0;
    if (!(cv > 0)) return mean;
    const k = 1 / (cv * cv);
    return gamma(k, mean / k);
  };
  return { next, normal, gamma, poisson, gammaMeanCv };
}

/** FNV-1a 32-bit hash of a string -> unsigned int. Use for seeds and content-addressed ids. */
export function fnv1a(str: string): number {
  let h = 0x811c9dc5;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 0x01000193);
  }
  return h >>> 0;
}

/** Deterministic seed from any string. */
export function seedFrom(str: string): number {
  return fnv1a(str);
}

/** Hex string of fnv1a, 8 chars. */
export function hashHex(str: string): string {
  return fnv1a(str).toString(16).padStart(8, '0');
}
